// Example: ML-DSA-65 + ECDSA-P256 hybrid signature
//
//	HybridAlgorithmParams {
//	  combiner_strategy: COMBINER_CONCATENATION
//	  components: [
//	    { algorithm: { ml_dsa: { parameter_set: ML_DSA_65 } }, label: "pqc",       order: 1 },
